function generateQuestions(subject,count,types){let base=demoBank[subject]||demoBank['الرياضيات'];let pool=base.filter(q=>types.includes(q.type));if(!pool.length)pool=base;const list=[];for(let i=0;i<count;i++){const src=pool[i%pool.length];list.push(Object.assign({},src,{id:'q'+Date.now().toString(36)+i,points:1}))}return list}
