function renderCurrentExam(){if(!currentExam)return;const x=currentExam;const meta=x.grade+' · '+x.subject+' · '+x.term+' · '+x.duration+' دقيقة · '+x.score+' درجة';document.getElementById('examMeta').textContent=meta+' — محتوى توضيحي للاختبار فقط';let out='<div class="exam-head"><h2>وزارة التربية والتعليم — نموذج تدريبي غير رسمي</h2><div>'+escapeHtml(x.stage)+' · '+escapeHtml(x.grade)+' · '+escapeHtml(x.year)+'</div><div>'+escapeHtml(x.subject)+' — '+escapeHtml(x.term)+'</div><div><b>'+escapeHtml(x.title)+'</b></div></div><div class="exam-student"><span>اسم الطالب: ........................................</span><span>الفصل: ...................</span><span>الزمن: '+x.duration+' دقيقة</span><span>الدرجة: '+x.score+'</span></div><p style="font-size:11px;color:#64748b;line-height:1.9">الوحدات: '+escapeHtml(x.units)+' · مستوى الصعوبة: '+escapeHtml(x.difficulty)+'</p>';x.questions.forEach(function(q,i){out+='<div class="exam-q"><p class="qtitle"><span class="qnum">'+(i+1)+'</span>'+escapeHtml(q.q)+' <span style="font-size:10px;color:#64748b;font-weight:400">('+q.points+' درجة)</span></p>';if(q.type==='mcq'||q.type==='tf'){out+='<div class="options">'+q.opts.map((o,j)=>'<div class="option"><i></i><span>'+optionLetter(j)+') '+escapeHtml(o)+'</span></div>').join('')+'</div>'}else{out+='<div class="shortanswer"></div><div class="shortanswer"></div>'}out+='<div class="qfoot">'+escapeHtml(normalizeType(q.type))+'</div></div>'});out+='<div class="doc-end"><span>انتهت الأسئلة — بالتوفيق</span><span>صفحة الامتحان · Hassty Lab</span></div>';document.getElementById('examPaper').innerHTML=out;document.getElementById('statQuestions').textContent=x.questions.length}
function buildWordHtml(x,includeAnswers){let s='<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><style>body{font-family:Tahoma,Arial,sans-serif;direction:rtl;color:#111;padding:24px}h2{text-align:center}table{width:100%;border-collapse:collapse}td,th{border:1px solid #555;padding:8px} .question{margin:16px 0;padding-bottom:10px;border-bottom:1px dashed #aaa} .options{padding-right:22px;line-height:2}</style></head><body>';s+='<h2>وزارة التربية والتعليم — نموذج تدريبي غير رسمي</h2><p style="text-align:center">'+escapeHtml(x.grade)+' · '+escapeHtml(x.subject)+' · '+escapeHtml(x.term)+' · '+escapeHtml(x.year)+'</p><h3 style="text-align:center">'+escapeHtml(x.title)+'</h3><p>اسم الطالب: ....................................　الفصل: ....................　الزمن: '+x.duration+' دقيقة　الدرجة: '+x.score+'</p><p>الوحدات: '+escapeHtml(x.units)+'</p>';x.questions.forEach(function(q,i){s+='<div class="question"><b>س'+(i+1)+'. '+escapeHtml(q.q)+'</b> ('+q.points+' درجة)';if(q.opts)s+='<div class="options">'+q.opts.map((o,j)=>optionLetter(j)+') '+escapeHtml(o)).join('<br>')+'</div>';else s+='<p>................................................................................................</p><p>................................................................................................</p>';s+='</div>'});if(includeAnswers&&x.answerKey!=='none'){s+='<div style="page-break-before:always"></div><h2>نموذج الإجابة — للمدرس</h2>';x.questions.forEach(function(q,i){let ans=q.opts?escapeHtml(q.opts[q.a]||''):escapeHtml(q.answer||'يُراجع بواسطة المدرس');s+='<p><b>س'+(i+1)+':</b> '+ans+' <span style="color:#666">('+q.points+' درجة)</span></p>'})}s+='</body></html>';return s}
function exportWord(){if(!currentExam){toast('أنشئ مسودة أولًا.');return}const doc=buildWordHtml(currentExam,true),blob=new Blob(['\ufeff',doc],{type:'application/msword;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=fileSafe(currentExam.title)+'.doc';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('تم تجهيز ملف Word قابل للتعديل.')}
