function renderStudentList(){const el=document.getElementById('studentList');if(!exams.length){el.innerHTML='<div class="empty"><div class="emptyicon">◉</div><b>لا توجد مسودات لتجربتها</b><p>أنشئ امتحانًا تجريبيًا واحفظه أولًا.</p><button class="btn primary" onclick="newExam()">إنشاء امتحان</button></div>';return}el.innerHTML=exams.map(function(x){return '<div class="recent-row"><div class="subject-icon">✎</div><div class="recent-info"><b>'+escapeHtml(x.title)+'</b><small>'+escapeHtml(x.grade)+' · '+escapeHtml(x.subject)+' · '+x.duration+' دقيقة</small></div><button class="btn primary small" onclick="startStudent('+x.id+')">ابدأ</button></div>'}).join('')}
function startStudent(id){const x=exams.find(e=>e.id===id);if(!x)return;let html='<div style="font-size:11px;color:#74819a;line-height:1.8;margin-bottom:15px">'+escapeHtml(x.grade)+' · '+escapeHtml(x.subject)+' · '+x.score+' درجة · '+x.duration+' دقيقة<br>هذه معاينة تجريبية ولا تحفظ نتيجة طالب.</div><form id="studentTest">';x.questions.forEach(function(q,i){html+='<div style="margin:17px 0;padding-bottom:14px;border-bottom:1px solid #edf0f6"><b style="font-size:12px;line-height:1.8">'+(i+1)+'. '+escapeHtml(q.q)+'</b>';if(q.opts){q.opts.forEach(function(o,j){html+='<label class="answeropt"><input type="radio" name="answer_'+i+'" value="'+j+'"><span>'+optionLetter(j)+') '+escapeHtml(o)+'</span></label>'})}else html+='<textarea name="answer_'+i+'" placeholder="اكتب إجابتك هنا (تقييمها يدوي)" style="width:100%;margin-top:10px;padding:10px;border:1px solid #dfe5ef;border-radius:10px;min-height:65px"></textarea>';html+='</div>'});html+='</form>';openModal('معاينة الطالب · '+x.title,html,'<button class="btn ghost" onclick="closeModal()">إنهاء المعاينة</button><button class="btn primary" onclick="submitStudent('+id+')">تسليم وحساب النتيجة</button>');window.__activeStudentId=id}
function submitStudent(id){const x=exams.find(e=>e.id===id);if(!x)return;let score=0,possible=0,answered=0;x.questions.forEach(function(q,i){possible+=q.points;const chosen=document.querySelector('#studentTest [name="answer_'+i+'"]:checked');if(q.opts){if(chosen){answered++;if(Number(chosen.value)===q.a)score+=q.points}}else{const text=document.querySelector('#studentTest [name="answer_'+i+'"]');if(text&&text.value.trim())answered++}});document.getElementById('modalTitle').textContent='نتيجة المعاينة';document.getElementById('modalBody').innerHTML='<div class="answerresult">الدرجة الموضوعية: '+score+' درجة</div><p style="font-size:12px;line-height:1.9;color:#68758d">عدد الأسئلة: '+x.questions.length+' · الإجابات المقدمة: '+answered+' · الدرجة الكلية: '+possible+'</p><p style="font-size:11px;line-height:1.8;color:#9b6809">الأسئلة المقالية لا تُصحح آليًا في هذه المعاينة. النتيجة تجريبية ولا تُحفظ كدرجة طالب.</p>';document.getElementById('modalFoot').innerHTML='<button class="btn primary" onclick="closeModal()">إغلاق</button>'}
