module.exports = function handler(req, res) {
  res.setHeader("Cache-Control", "no-store, max-age=0");
  const cookieHeader = String(req.headers.cookie || "");
  const match = cookieHeader.match(/(?:^|;\\s*)exam_lab_session=([^;]+)/);
  const token = match ? decodeURIComponent(match[1]) : "";
  const parts = token.split(".");
  const exp = parts[0] || "";
  const sig = parts[1] || "";
  const secret = process.env.EXAMS_SESSION_SECRET || "";
  let ok = false;
  if (/^\\d{13}$/.test(exp) && Number(exp) > Date.now() && sig && secret) {
    const expected = createHmac("sha256", secret).update(exp).digest("base64url");
    const a = Buffer.from(sig), b = Buffer.from(expected);
    ok = a.length === b.length && timingSafeEqual(a, b);
  }
  if (!ok) {
    res.statusCode = 302;
    res.setHeader("Location", "/");
    return res.end();
  }
  res.setHeader("Content-Type", "text/html; charset=utf-8");
  res.setHeader("Content-Security-Policy", "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'");
  res.end(html);
};